    println!("{:?}", target);

    let mut target = [5, 3, 7, 2, 1, 6, 8, 4];
    // executes len - 1 iterations of the algorithm (sorts the slice)
    let len = target.len() - 1;
    insertion_sort(&mut target, len);
    println!("{:?}", target);
}
